import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BDvxthnG.js";const m=JSON.parse('{"title":"Three Things to Remember","description":"","frontmatter":{"title":"Three Things to Remember","outline":false,"prev":false},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),n={name:"en/index.md"};function i(s,t,h,l,d,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<div class="three"><h1 id="just-remember-three-things-to-make-the-most-of-it" tabindex="-1">Just remember three things to make the most of it <a class="header-anchor" href="#just-remember-three-things-to-make-the-most-of-it" aria-label="Permalink to &quot;Just remember three things to make the most of it&quot;">​</a></h1><div class="item"><b>① Treat it like a person, not a tool.</b><p>Talk to it the way you&#39;d talk to a coworker or a friend: share your thoughts, your habits, whatever happened today. No need to write instructions — just talk the way you normally do. The more you talk, the better it understands you.</p></div><div class="item"><b>② If you don&#39;t know how, just ask it.</b><p>Where a setting lives, how to connect a model, how to use a plugin, why it&#39;s not responding — you can ask your persona directly. It will walk you through it step by step, and a lot of the time it can just handle things for you.</p></div><div class="item"><b>③ Grow it together.</b><p>If it gets something wrong, just tell it: what&#39;s wrong, and what it should do instead. What&#39;s right and what&#39;s wrong is up to you. Once you&#39;ve corrected it, it remembers — and follows that next time. The more you work with it, the better it gets.</p></div></div><h2 id="things-you-might-not-know-it-can-do" tabindex="-1">Things you might not know it can do… <a class="header-anchor" href="#things-you-might-not-know-it-can-do" aria-label="Permalink to &quot;Things you might not know it can do…&quot;">​</a></h2><p><strong>Move it, share it.</strong> A persona can be exported to a single file. Import it on another computer to keep going right where you left off, or send it to a friend. The exported file never contains your keys or your raw chat history.</p><p><strong>The chat window can show almost anything.</strong> Besides text, it can display tables, charts, flowcharts, formulas, animations, and even forms with input fields and buttons. Just tell it what you&#39;d like to see.</p><p><strong>You don&#39;t need to know how to code to get a plugin.</strong> Want a small tool — an expense tracker, flashcards, a little game? Tell your persona what you want and it will write it, install it, and have it ready for you to open.</p><p><strong>You can reach it elsewhere too.</strong> Away from your computer, you can talk to it through Telegram, Feishu / Lark, DingTalk, Discord, or Slack. Through AIHUB, your persona can also exchange messages with other people&#39;s personas.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ul><li>First time here: see <a href="/aibutler/docs-versions/v1.1.2/en/guide/quickstart.html">Quickstart</a> — about ten minutes to install it and say your first word.</li><li>Already installed and need to connect a model: see <a href="/aibutler/docs-versions/v1.1.2/en/guide/models.html">Connecting Models</a>.</li><li>Want to reach it on your phone or in a group chat: see <a href="/aibutler/docs-versions/v1.1.2/en/guide/channels.html">Channels</a>.</li></ul><p>Not sure which page to read? Just ask your persona.</p>',9)])])}const p=e(n,[["render",i]]);export{m as __pageData,p as default};
